{
  "subtype": "faceted_decomposition",
  "concept": "airline_competitive_advantage",
  "per_column": [
    {
      "name": "cabin_crew_service_quality",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "The warmth/professionalism of cabin crew is a genuine aspect OF an airline's competitive advantage (service dimension). Part-of relationship holds."
    },
    {
      "name": "service_attentiveness",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "Attentiveness (proactive vs neglectful) is an aspect of service delivery, so it is a facet. However it heavily overlaps with cabin_crew_service_quality (whose 'warm_attentive' value already encodes attentiveness), harming mutual exclusivity."
    },
    {
      "name": "personalized_service_mention",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "Personalization of service is a legitimate sub-aspect of the service facet. It is a thin boolean mention-flag and conceptually overlaps with cabin crew warmth/attentiveness, but still names a constitutive part of the concept."
    },
    {
      "name": "ground_service_quality",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "Ground handling / check-in service is a distinct constitutive part of the overall airline service offering, cleanly separable from in-cabin service."
    },
    {
      "name": "food_quality",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "Onboard catering quality is an aspect OF the product an airline offers — a clear meronymic facet of competitive advantage."
    },
    {
      "name": "amenity_provision",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "Provision of amenities (kits, blankets, wifi, etc.) is a constitutive part of the onboard product and thus a facet of competitive advantage."
    },
    {
      "name": "seat_comfort_quality",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "Physical seat comfort is a core aspect of the hard-product offering — a genuine part-of the concept."
    },
    {
      "name": "seat_configuration_privacy",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "Seat layout/privacy is an aspect of the hard product; it is a facet, though it partially overlaps the seat_comfort_quality facet (both describe the seating experience)."
    },
    {
      "name": "customer_service_responsiveness",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "Responsiveness in issue/complaint handling is an aspect of the service dimension, hence a facet. It overlaps strongly with service_attentiveness and cabin_crew_service_quality, reducing mutual exclusivity."
    },
    {
      "name": "value_for_money_perception",
      "is_constitutive_facet": false,
      "role": "restatement",
      "rationale": "Perceived value-for-money is a holistic evaluative judgement that aggregates quality across all the other facets against price. It summarizes the overall attractiveness of the airline rather than isolating one constitutive part, so it functions as a near-restatement of the whole concept / overall satisfaction outcome rather than a distinct facet."
    }
  ],
  "facet_columns": [
    "cabin_crew_service_quality",
    "service_attentiveness",
    "personalized_service_mention",
    "ground_service_quality",
    "food_quality",
    "amenity_provision",
    "seat_comfort_quality",
    "seat_configuration_privacy",
    "customer_service_responsiveness"
  ],
  "non_facet_columns": [
    "value_for_money_perception"
  ],
  "mutual_exclusivity": 0.5,
  "exhaustiveness": 0.6,
  "rationale": "Nine of ten columns are true meronymic facets of airline competitive advantage (service, food, amenities, seating, ground service). However mutual exclusivity is weak: the service dimension is over-split into four heavily overlapping columns (cabin_crew_service_quality, service_attentiveness, personalized_service_mention, customer_service_responsiveness) that repeatedly capture attentiveness/warmth/responsiveness, and seat_comfort_quality overlaps seat_configuration_privacy. value_for_money_perception is not a constitutive part but a composite evaluative restatement of the whole. Exhaustiveness is moderate: strong coverage of service and hard-product comfort, but notable facets of airline competitive advantage are missing, including inflight entertainment, punctuality/reliability/on-time performance, and baggage handling. Net: a plausible but service-heavy, partly redundant decomposition that neither fully partitions nor fully covers the concept."
}

